import { expect, test } from 'playwright/test'
import { PageManager } from '../pages/pageManager'

test.beforeEach(async ({ page }) => {
  await page.goto('http://localhost:5173')
})

const MESSAGE = 'Hello there!'
const REPLY = 'GENERAL KENOBI!!'

test.describe('Chat', () => {
  test('chat screen shows main UI controls', async ({ page }) => {
    const pageManager = new PageManager(page)
    const chat = pageManager.onChatPage()

    await expect(chat.funnyModeCheckbox).toBeEnabled({ timeout: 15_000 })
    await expect(chat.funnyModeCheckbox).toBeVisible()
    await expect(chat.loadingLabel).toBeHidden()
    await expect(chat.chatWindow).toBeVisible()
    await expect(chat.messageList).toBeVisible()
    await expect(chat.sectionDivider).toBeVisible()
    await expect(chat.messageInput).toBeVisible()
    await expect(chat.sendButton).toBeVisible()
    await expect(chat.resetChatButton).toBeVisible()
  })

  test('Should be able to send a message', async ({ page }) => {
    const pageManager = new PageManager(page)
    const chat = pageManager.onChatPage()

    await chat.fillChatInput(MESSAGE)
    await chat.sendMessage()
    await expect(chat.chatMessageFirst).toBeVisible()
    await expect(chat.chatMessageFirstReply).toBeVisible()
    expect(await chat.getChatMessageFirstText()).toBe(MESSAGE)
    expect(await chat.getChatMessageFirstReplyText()).toBe(REPLY)
  })
})
=====PAGEMANAGER=====
import type { Page } from '@playwright/test'
import { AppLayoutPage } from './layout/appLayoutPage'
import { ChatPage } from './chat/chatPage'
import { HelpPage } from './helpPage'
import { SearchPage } from './searchPage'

export class PageManager {
  private readonly page: Page
  private readonly appLayoutPage: AppLayoutPage
  private readonly chatPage: ChatPage
  private readonly searchPage: SearchPage
  private readonly helpPage: HelpPage

  constructor(page: Page) {
    this.page = page
    this.appLayoutPage = new AppLayoutPage(this.page)
    this.chatPage = new ChatPage(this.page)
    this.searchPage = new SearchPage(this.page)
    this.helpPage = new HelpPage(this.page)
  }

  onAppLayout() {
    return this.appLayoutPage
  }

  onChatPage() {
    return this.chatPage
  }

  onSearchPage() {
    return this.searchPage
  }

  onHelpPage() {
    return this.helpPage
  }
}=====CHATPAGE=====
import type { Locator, Page } from '@playwright/test'

export class ChatPage {
  /** Shell & status */
  readonly funnyModeCheckbox: Locator
  readonly loadingLabel: Locator
  readonly chatWindow: Locator
  readonly messageList: Locator
  readonly sectionDivider: Locator

  /** Composer */
  readonly messageInput: Locator
  readonly sendButton: Locator
  readonly resetChatButton: Locator

  /** Thread */
  readonly chatMessageFirst: Locator
  readonly chatMessageFirstReply: Locator

  constructor(page: Page) {
    this.funnyModeCheckbox = page.getByRole('checkbox', {
      name: /funny mode/i,
    })
    this.loadingLabel = page.getByText('Loading…')
    this.chatWindow = page.locator('.chat-window')
    this.messageList = page.locator('.chat-window__list')
    this.sectionDivider = page.locator('.chat-window__divider')

    this.messageInput = page.getByPlaceholder('Type a message…')
    this.sendButton = page.getByRole('button', { name: 'Send' })
    this.resetChatButton = page.getByRole('button', { name: 'Reset Chat' })

    this.chatMessageFirst = page
      .locator('.chat-message--user')
      .first()
      .locator('.chat-message__bubble')
    // Exclude .chat-message--loading: the "Thinking…" placeholder shares
    // .chat-message--assistant with the real reply while it's pending, so
    // an unqualified first() can transiently match the placeholder instead.
    this.chatMessageFirstReply = page
      .locator('.chat-message--assistant:not(.chat-message--loading)')
      .first()
      .locator('.chat-message__bubble')
  }

  async sendMessage() {
    await this.sendButton.click()
  }

  async fillChatInput(message: string) {
    await this.messageInput.fill(message)
  }

  async getChatMessageFirstText() {
    return await this.chatMessageFirst.textContent()
  }

  async getChatMessageFirstReplyText() {
    return await this.chatMessageFirstReply.textContent()
  }
}

